/**
 * Element #3: Draw Heading Direction - Traditional Compass Rose (Top Center)
 */
function drawHeadingCompass() {
    const centerX = DISPLAY.ATTITUDE_CENTER_X;
    const centerY = 60;
    const roseSize = 80;
    const heading = smoothedValues.heading;

    // No background - transparent overlay

    // Traditional compass rose design with N, E, S, W points
    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.rotate(-heading * Math.PI / 180); // Rotate compass rose, not aircraft

    // Draw cardinal direction markers (transparent background)
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = 'bold 16px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // North (top)
    ctx.fillText('N', 0, -roseSize/2 - 15);

    // East (right)
    ctx.fillText('E', roseSize/2 + 15, 0);

    // South (bottom)
    ctx.fillText('S', 0, roseSize/2 + 15);

    // West (left)
    ctx.fillText('W', -roseSize/2 - 15, 0);

    // Draw intercardinal directions
    ctx.font = '12px Arial';
    ctx.fillText('NE', roseSize/2 * 0.707, -roseSize/2 * 0.707 - 10);
    ctx.fillText('SE', roseSize/2 * 0.707, roseSize/2 * 0.707 + 10);
    ctx.fillText('SW', -roseSize/2 * 0.707, roseSize/2 * 0.707 + 10);
    ctx.fillText('NW', -roseSize/2 * 0.707, -roseSize/2 * 0.707 - 10);

    // Draw compass rose lines
    ctx.strokeStyle = COLORS.TEXT_WHITE;
    ctx.lineWidth = 2;

    // Main cross (N-S, E-W)
    ctx.beginPath();
    ctx.moveTo(0, -roseSize/2);
    ctx.lineTo(0, roseSize/2);
    ctx.moveTo(-roseSize/2, 0);
    ctx.lineTo(roseSize/2, 0);
    ctx.stroke();

    // Diagonal cross (NE-SW, NW-SE)
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-roseSize/2 * 0.707, -roseSize/2 * 0.707);
    ctx.lineTo(roseSize/2 * 0.707, roseSize/2 * 0.707);
    ctx.moveTo(roseSize/2 * 0.707, -roseSize/2 * 0.707);
    ctx.lineTo(-roseSize/2 * 0.707, roseSize/2 * 0.707);
    ctx.stroke();

    // Draw degree tick marks around rose
    for (let deg = 0; deg < 360; deg += 10) {
        const angle = deg * Math.PI / 180;
        const tickLength = deg % 30 === 0 ? 8 : 4;
        const startRadius = roseSize/2 - 5;
        const endRadius = startRadius - tickLength;

        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = deg % 90 === 0 ? 2 : 1;
        ctx.beginPath();
        ctx.moveTo(
            Math.cos(angle) * startRadius,
            Math.sin(angle) * startRadius
        );
        ctx.lineTo(
            Math.cos(angle) * endRadius,
            Math.sin(angle) * endRadius
        );
        ctx.stroke();
    }

    ctx.restore();

    // Fixed aircraft heading indicator (always points up)
    ctx.fillStyle = COLORS.TEXT_YELLOW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY - roseSize/2 - 5);
    ctx.lineTo(centerX - 6, centerY - roseSize/2 + 5);
    ctx.lineTo(centerX + 6, centerY - roseSize/2 + 5);
    ctx.closePath();
    ctx.fill();

    // Digital heading display (fixed position)
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = 'bold 16px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`${Math.round(heading).toString().padStart(3, '0')}°`, centerX, centerY + roseSize/2 + 25);
}

tool_input.new_string:
/**
 * Element #3: Draw Heading Direction - Horizontal Heading Tape (Top Center)
 */
function drawHeadingCompass() {
    const centerX = DISPLAY.ATTITUDE_CENTER_X;
    const centerY = 30;
    const tapeWidth = 400;
    const tapeHeight = 40;
    const heading = smoothedValues.heading;

    // Draw horizontal heading tape background (no black background)
    const tapeX = centerX - tapeWidth/2;

    // Heading tape markings
    ctx.strokeStyle = COLORS.TEXT_WHITE;
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = '12px Arial';
    ctx.textAlign = 'center';
    ctx.lineWidth = 1;

    // Calculate visible heading range
    const degreesPerPixel = 0.5; // 0.5 degrees per pixel
    const halfRange = (tapeWidth/2) * degreesPerPixel;

    // Draw heading markings
    for (let deg = Math.floor(heading - halfRange); deg <= Math.ceil(heading + halfRange); deg += 10) {
        let displayDeg = deg;
        if (displayDeg < 0) displayDeg += 360;
        if (displayDeg >= 360) displayDeg -= 360;

        const pixelOffset = (deg - heading) / degreesPerPixel;
        const x = centerX + pixelOffset;

        if (x < tapeX || x > tapeX + tapeWidth) continue;

        // Major tick marks every 30 degrees
        if (displayDeg % 30 === 0) {
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(x, centerY - 15);
            ctx.lineTo(x, centerY + 5);
            ctx.stroke();

            // Cardinal direction labels
            let label = displayDeg.toString();
            if (displayDeg === 0) label = 'N';
            else if (displayDeg === 90) label = 'E';
            else if (displayDeg === 180) label = 'S';
            else if (displayDeg === 270) label = 'W';
            else label = (displayDeg / 10).toString();

            ctx.fillText(label, x, centerY - 20);
        } else {
            // Minor tick marks
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(x, centerY - 10);
            ctx.lineTo(x, centerY + 5);
            ctx.stroke();
        }
    }

    // Center heading indicator (fixed yellow triangle pointing down)
    ctx.fillStyle = COLORS.TEXT_YELLOW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + 8);
    ctx.lineTo(centerX - 8, centerY - 5);
    ctx.lineTo(centerX + 8, centerY - 5);
    ctx.closePath();
    ctx.fill();

    // Digital heading display (no background - transparent text)
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = 'bold 16px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`${Math.round(heading).toString().padStart(3, '0')}°`, centerX, centerY + 30);
}

